// 從尾端開始填：比較兩個陣列的最大值，放到 nums1 最後面
// 時間複雜度: O(m + n)，空間複雜度: O(1)
function merge(nums1, m, nums2, n) {
    let i = m - 1, j = n - 1, k = m + n - 1;
    while (j >= 0) {
        if (i >= 0 && nums1[i] > nums2[j])
            nums1[k--] = nums1[i--];
        else
            nums1[k--] = nums2[j--];
    }
}

